INSERT INTO flair_challenges (id, slug, name, names_json, description, descriptions_json, scenario, difficulty, status, moment_id, slots_json, requirements_json, theme_tags, points, repeat_limit, group_code, locks_cards, official, sort_order, version, created_at, updated_at, series, game_number, district, rarity, required_level, required_wardrobe_level, deck_json, hype_json, ficha_json, scene_json, rewards_json, thumbnail) VALUES
('7d000000-0000-4000-8000-000000000038','b38-passarela-de-gelo','Passarela de Gelo','{"pt-BR":"Passarela de Gelo","en":"Ice Runway","es":"Pasarela de Hielo"}','Desfilar numa passarela de gelo onde cada peça leve derrete uma placa e cada peça de inverno a congela de volta.','{"pt-BR":"Desfilar numa passarela de gelo onde cada peça leve derrete uma placa e cada peça de inverno a congela de volta.","en":"Walk an ice runway where every light piece melts a plate and every winter piece freezes it back.","es":"Desfilar en una pasarela de hielo donde cada prenda ligera derrite una placa y cada prenda de invierno la vuelve a congelar."}','livre','HARD','ACTIVE',NULL,'[{"key":"placa_1_congela","position":"SUP","accepts":{},"label":{"pt-BR":"Placa 1: congela","en":"Plate 1: freeze","es":"Placa 1: congela"},"story":{"pt-BR":"Na placa 1, {name}{brand, select, none {} other { da {brand}}} congela o primeiro passo.","en":"On plate 1, {name}{brand, select, none {} other { by {brand}}} freezes the first step.","es":"En la placa 1, {name}{brand, select, none {} other { de {brand}}} congela el primer paso."},"effects":{"comum":{"pt-BR":"A placa 1: congela congela ou derrete, e derreter custa um passo.","en":"The plate 1: freeze freezes or melts, and melting costs a step.","es":"La placa 1: congela se congela o se derrite, y derretirse cuesta un paso."},"metamorfose":{"pt-BR":"A placa 1: congela vira vidro-gelo permanente e a seguinte não derrete.","en":"The plate 1: freeze turns to permanent ice glass and the next one does not melt.","es":"La placa 1: congela se vuelve vidrio-hielo permanente y la siguiente no se derrite."},"impersonation":{"pt-BR":"O avatar atravessa a placa 1: congela vestindo a peça de inverno e congela duas placas.","en":"The avatar crosses the plate 1: freeze wearing the winter piece and freezes two plates.","es":"El avatar cruza la placa 1: congela con la prenda de invierno puesta y congela dos placas."}},"bonus":{"metamorfose":1,"impersonation":2}},{"key":"placa_2_livre","position":"INF","accepts":{},"label":{"pt-BR":"Placa 2: livre","en":"Plate 2: free","es":"Placa 2: libre"},"story":{"pt-BR":"Na placa 2, {name}{brand, select, none {} other { da {brand}}} arrisca um passo leve.","en":"On plate 2, {name}{brand, select, none {} other { by {brand}}} risks a light step.","es":"En la placa 2, {name}{brand, select, none {} other { de {brand}}} arriesga un paso ligero."},"effects":{"comum":{"pt-BR":"A placa 2: livre congela ou derrete, e derreter custa um passo.","en":"The plate 2: free freezes or melts, and melting costs a step.","es":"La placa 2: libre se congela o se derrite, y derretirse cuesta un paso."},"metamorfose":{"pt-BR":"A placa 2: livre vira vidro-gelo permanente e a seguinte não derrete.","en":"The plate 2: free turns to permanent ice glass and the next one does not melt.","es":"La placa 2: libre se vuelve vidrio-hielo permanente y la siguiente no se derrite."},"impersonation":{"pt-BR":"O avatar atravessa a placa 2: livre vestindo a peça de inverno e congela duas placas.","en":"The avatar crosses the plate 2: free wearing the winter piece and freezes two plates.","es":"El avatar cruza la placa 2: libre con la prenda de invierno puesta y congela dos placas."}},"bonus":{"metamorfose":1,"impersonation":2}},{"key":"placa_3_congela","position":"SUP","accepts":{},"label":{"pt-BR":"Placa 3: congela","en":"Plate 3: freeze","es":"Placa 3: congela"},"story":{"pt-BR":"Na placa 3, {name}{brand, select, none {} other { da {brand}}} devolve o gelo com uma camada de inverno.","en":"On plate 3, {name}{brand, select, none {} other { by {brand}}} brings the ice back with a winter layer.","es":"En la placa 3, {name}{brand, select, none {} other { de {brand}}} devuelve el hielo con una capa de invierno."},"effects":{"comum":{"pt-BR":"A placa 3: congela congela ou derrete, e derreter custa um passo.","en":"The plate 3: freeze freezes or melts, and melting costs a step.","es":"La placa 3: congela se congela o se derrite, y derretirse cuesta un paso."},"metamorfose":{"pt-BR":"A placa 3: congela vira vidro-gelo permanente e a seguinte não derrete.","en":"The plate 3: freeze turns to permanent ice glass and the next one does not melt.","es":"La placa 3: congela se vuelve vidrio-hielo permanente y la siguiente no se derrite."},"impersonation":{"pt-BR":"O avatar atravessa a placa 3: congela vestindo a peça de inverno e congela duas placas.","en":"The avatar crosses the plate 3: freeze wearing the winter piece and freezes two plates.","es":"El avatar cruza la placa 3: congela con la prenda de invierno puesta y congela dos placas."}},"bonus":{"metamorfose":1,"impersonation":2}},{"key":"placa_4_livre","position":"CAL","accepts":{},"label":{"pt-BR":"Placa 4: bota","en":"Plate 4: boots","es":"Placa 4: bota"},"story":{"pt-BR":"Na placa 4, {name}{brand, select, none {} other { da {brand}}} pisa o gelo com sola firme.","en":"On plate 4, {name}{brand, select, none {} other { by {brand}}} treads the ice with a firm sole.","es":"En la placa 4, {name}{brand, select, none {} other { de {brand}}} pisa el hielo con suela firme."},"effects":{"comum":{"pt-BR":"A placa 4: bota congela ou derrete, e derreter custa um passo.","en":"The plate 4: boots freezes or melts, and melting costs a step.","es":"La placa 4: bota se congela o se derrite, y derretirse cuesta un paso."},"metamorfose":{"pt-BR":"A placa 4: bota vira vidro-gelo permanente e a seguinte não derrete.","en":"The plate 4: boots turns to permanent ice glass and the next one does not melt.","es":"La placa 4: bota se vuelve vidrio-hielo permanente y la siguiente no se derrite."},"impersonation":{"pt-BR":"O avatar atravessa a placa 4: bota vestindo a peça de inverno e congela duas placas.","en":"The avatar crosses the plate 4: boots wearing the winter piece and freezes two plates.","es":"El avatar cruza la placa 4: bota con la prenda de invierno puesta y congela dos placas."}},"bonus":{"metamorfose":1,"impersonation":2}},{"key":"placa_5_congela","position":"ACE","